package com.example
import kotlin.math.*
/** KDoc */
@Serializable data class User(val name: String, var age: Int = 0, val tags: List<String>? = null)
sealed interface Result<out T> { class Ok<T>(val v: T) : Result<T>; object Err : Result<Nothing> }
fun main(args: Array<String>) {
    val s = "esc \" \$x \${y} ${args.size}"; val raw = """raw $s"""; val c = 'a'; val n = 0x1F + 1_000L + 3.14f
    var x: Int? = null; x?.let { println(it) } ?: run { println("none") }
